BEGIN;
CREATE TYPE "TipoDestinacaoRecebimento" AS ENUM ('COBRANCA','CREDITO_SEM_DESTINO');
ALTER TABLE "Recebimento" ALTER COLUMN "cobrancaId" DROP NOT NULL;
ALTER TABLE "Recebimento" ADD COLUMN "titularMatriculaId" text REFERENCES "Matricula"(id) ON DELETE RESTRICT, ADD COLUMN "pagadorId" text;
UPDATE "Recebimento" r SET "titularMatriculaId"=c."matriculaId" FROM "Cobranca" c WHERE c.id=r."cobrancaId";
CREATE TABLE "DestinacaoRecebimento" (id text PRIMARY KEY,"recebimentoId" text NOT NULL REFERENCES "Recebimento"(id) ON DELETE RESTRICT,"cobrancaId" text REFERENCES "Cobranca"(id) ON DELETE RESTRICT,"autorId" text NOT NULL REFERENCES "Usuario"(id) ON DELETE RESTRICT,tipo "TipoDestinacaoRecebimento" NOT NULL,valor decimal(12,2) NOT NULL,evidencia text NOT NULL,"chaveIdempotencia" text NOT NULL,"criadaEm" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("recebimentoId","chaveIdempotencia"),CHECK(valor>0),CHECK((tipo='COBRANCA' AND "cobrancaId" IS NOT NULL) OR (tipo='CREDITO_SEM_DESTINO' AND "cobrancaId" IS NULL)));
ALTER TABLE "CreditoMatricula" ADD COLUMN "origemDestinacaoRecebimentoId" text UNIQUE REFERENCES "DestinacaoRecebimento"(id) ON DELETE RESTRICT;
INSERT INTO "DestinacaoRecebimento"(id,"recebimentoId","cobrancaId","autorId",tipo,valor,evidencia,"chaveIdempotencia","criadaEm") SELECT 'legado-dest-'||r.id,r.id,r."cobrancaId",r."autorId",'COBRANCA',r.valor,'Recebimento legado preservado','legado:'||r.id,r."criadoEm" FROM "Recebimento" r WHERE r."cobrancaId" IS NOT NULL;
CREATE FUNCTION conferir_destinacao_recebimento_211() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE r "Recebimento"; c "Cobranca"; BEGIN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Destinação imutável'; END IF; SELECT * INTO r FROM "Recebimento" WHERE id=NEW."recebimentoId" FOR UPDATE; IF r."titularMatriculaId" IS NULL THEN RAISE EXCEPTION 'Titular pendente'; END IF; IF NEW.tipo='COBRANCA' THEN SELECT * INTO c FROM "Cobranca" WHERE id=NEW."cobrancaId" FOR UPDATE; IF c."matriculaId" IS DISTINCT FROM r."titularMatriculaId" OR c.moeda IS DISTINCT FROM r.moeda THEN RAISE EXCEPTION 'Destino incompatível'; END IF; END IF; IF (SELECT coalesce(sum(valor),0) FROM "DestinacaoRecebimento" WHERE "recebimentoId"=NEW."recebimentoId")+NEW.valor>r.valor THEN RAISE EXCEPTION 'Excede recebimento'; END IF; RETURN NEW; END $$;
CREATE TRIGGER conferir_destinacao_recebimento BEFORE INSERT OR UPDATE OR DELETE ON "DestinacaoRecebimento" FOR EACH ROW EXECUTE FUNCTION conferir_destinacao_recebimento_211();
COMMIT;
